379	    #[test]
380	    fn test_features_small_instance() {
381	        let stops = vec![
382	            make_stop(0.0, 0.0, "depot"),
383	            make_stop(1.0, 0.0, "a"),
384	            make_stop(0.0, 1.0, "b"),
385	        ];
386	        let input = make_input(stops, 1);
387	        let f = RouteFeatures::from_input(&input);
388	        assert_eq!(f.num_stops, 2);
389	        assert!(f.avg_pairwise_km > 0.0);
390	        assert!(!f.tight_capacity);
391	    }
392	
393	    #[test]
394	    fn test_predict_solver_returns_valid_id() {
395	        let stops = vec![
396	            make_stop(0.0, 0.0, "depot"),
397	            make_stop(1.0, 0.0, "a"),
398	            make_stop(2.0, 0.0, "b"),
399	            make_stop(3.0, 0.0, "c"),
400	        ];
401	        let input = make_input(stops, 1);
402	        let features = RouteFeatures::from_input(&input);
403	        let pred = predict_solver(&features);
404	        assert!(!pred.recommended.is_empty());
405	        assert!(pred.confidence > 0.0 && pred.confidence <= 1.0);
406	        assert_eq!(pred.all_scores.len(), 5);
407	    }
408	
409	    #[test]
410	    fn test_route_feature_vector_dim() {
411	        let stops = vec![make_stop(0.0, 0.0, "depot"), make_stop(1.0, 0.0, "a")];
412	        let input = make_input(stops, 1);
413	        let features = RouteFeatures::from_input(&input);
414	        let vec = route_feature_vector(&features);
415	        assert_eq!(vec.len(), 12);
416	        for v in &vec {
417	            assert!(*v >= 0.0 && *v <= 1.0, "feature out of range: {}", v);
418	        }
419	    }
420	
421	    #[test]
422	    fn test_score_route_basic() {
423	        let stops = vec![
424	            make_stop(0.0, 0.0, "depot"),
425	            make_stop(1.0, 0.0, "a"),
426	            make_stop(0.0, 1.0, "b"),
427	        ];
428	        let input = make_input(stops.clone(), 1);
429	        let output = VRPSolverOutput {
430	            stops: stops.clone(),
431	            routes: Some(vec![stops.clone()]),
432	            total_distance_km: "3.0".into(),
433	            total_time_min: 10,
434	            route_stats: None,
435	            route_metrics: None,
436	            unassigned: None,
437	        };
438	        let score = score_route(&input, &output);
439	        assert!(score.overall >= 0.0 && score.overall <= 100.0);
440	        assert!(score.coverage >= 99.0); // all stops assigned
441	    }
442	}

