 21	//! Core types for the VRP solver system.
 22	
 23	use serde::{Deserialize, Serialize};
 24	
 25	/// Internal solve result shared across all VRP solvers.
 26	pub(crate) struct SolveResult {
 27	    pub routes: Vec<Vec<usize>>,
 28	    pub total_distance: f64,
 29	    pub total_time: f64,
 30	}
 31	
 32	impl SolveResult {
 33	    pub fn into_output(self, input: &VRPSolverInput) -> VRPSolverOutput {
 34	        let routes: Vec<Vec<VRPSolverStop>> = self
 35	            .routes
 36	            .iter()
 37	            .map(|r| r.iter().map(|&i| input.locations[i].clone()).collect())
 38	            .collect();
 39	        VRPSolverOutput {
 40	            stops: routes.iter().flatten().cloned().collect(),
 41	            routes: Some(routes),
 42	            total_distance_km: format!("{:.2}", self.total_distance),
 43	            total_time_min: (self.total_time / 60.0).round() as u32,
 44	            route_stats: None,
 45	            route_metrics: None,
 46	            unassigned: None,
 47	        }
 48	    }
 49	}
