 258	// ── Bearing calculation ──────────────────────────────────────────────
 259	
 260	/// Calculate the initial bearing from point 1 to point 2 in degrees.
 261	fn bearing(lat1: f64, lon1: f64, lat2: f64, lon2: f64) -> f64 {
 262	    let dlon = (lon2 - lon1).to_radians();
 263	    let lat1_r = lat1.to_radians();
 264	    let lat2_r = lat2.to_radians();
 265	
 266	    let x = dlon.cos() * lat2_r.sin();
 267	    let y = lat1_r.cos() * lat2_r.sin() - lat1_r.sin() * lat2_r.cos() * dlon.cos();
 268	
 269	    let bearing_rad = y.atan2(x);
 270	    (bearing_rad.to_degrees() + 360.0) % 360.0
 271	}
