 571	/// Run the Vehicle Routing Problem optimization.
 572	async fn run_vrp_optimize(req: &OptimizeRequest) -> anyhow::Result<OptimizeResult> {
 573	    let start = Instant::now();
 574	
 575	    // 1. Read .rmp
 576	    let mut file_data = Vec::new();
 577	    std::fs::File::open(&req.cache_file)?.read_to_end(&mut file_data)?;
 578	    let (nodes, _edges) = read_rmp_file(&file_data)?;
 579	
 580	    if nodes.is_empty() {
 581	        anyhow::bail!("No nodes found in .rmp file");
 582	    }
 583	
 584	    // 2. Build VRP Stops
 585	    let mut stops: Vec<VRPSolverStop> = nodes
 586	        .iter()
 587	        .enumerate()
 588	        .map(|(i, n)| VRPSolverStop {
 589	            lat: n.lat,
 590	            lon: n.lon,
 591	            label: format!("Node {}", i),
 592	            demand: Some(1.0),
 593	            arrival_time: None,
 594	        })
 595	        .collect();
 596	
 597	    // Add depot at start if specified
 598	    if let Some((dlat, dlon)) = req.depot {
 599	        stops.insert(
 600	            0,
 601	            VRPSolverStop {
 602	                lat: dlat,
 603	                lon: dlon,
 604	                label: "Depot".into(),
 605	                demand: Some(0.0),
 606	                arrival_time: None,
 607	            },
 608	        );
 609	    }
 610	
 611	    // 3. Build Distance Matrix (Haversine for now)
 612	    let matrix = super::vrp::utils::build_haversine_matrix(&stops, 40.0);
 613	
 614	    // 4. Solve
 615	    let vrp_input = VRPSolverInput {
 616	        locations: stops.clone(),
 617	        num_vehicles: req.num_vehicles,
 618	        vehicle_capacity: (stops.len() as f64 / req.num_vehicles as f64).ceil() * 1.5,
 619	        objective: VrpObjective::MinDistance,
 620	        matrix: Some(matrix),
 621	        service_time_secs: Some(30.0),
 622	        use_time_windows: false,
 623	        window_open: None,
 624	        window_close: None,
 625	    };
 626	
 627	    let output = solve_with(&req.solver_id, &vrp_input)
 628	        .await
 629	        .map_err(|e| anyhow::anyhow!("VRP Solver error: {}", e))?;
 630	
 631	    // 5. Compute Stats
 632	    let mut turns = TurnSummary {
 633	        left: 0,
 634	        right: 0,
 635	        u_turn: 0,
 636	        straight: 0,
 637	    };
 638	
 639	    if let Some(ref routes) = output.routes {
 640	        for route in routes {
 641	            if route.len() > 2 {
 642	                for i in 1..route.len() - 1 {
 643	                    let prev = &route[i - 1];
 644	                    let curr = &route[i];
 645	                    let next = &route[i + 1];
 646	                    let b_in = bearing(prev.lat, prev.lon, curr.lat, curr.lon);
 647	                    let b_out = bearing(curr.lat, curr.lon, next.lat, next.lon);
 648	                    let b_in_rev = (b_in + 180.0) % 360.0;
 649	                    let delta = b_out - b_in_rev;
 650	                    match classify_turn(delta) {
 651	                        "left" => turns.left += 1,
 652	                        "right" => turns.right += 1,
 653	                        "u_turn" => turns.u_turn += 1,
 654	                        _ => turns.straight += 1,
 655	                    }
 656	                }
 657	            }
 658	        }
 659	    }
 660	
 661	    let total_dist_km: f64 = output.total_distance_km.parse().unwrap_or(0.0);
 662	
 663	    // 6. Write GPX
 664	    if let Some(ref path) = req.route_file {
 665	        if let Some(ref routes) = output.routes {
 666	            write_gpx_multi(path, routes)?;
 667	        }
 668	    }
 669	
 670	    Ok(OptimizeResult {
 671	        total_distance_km: total_dist_km,
 672	        total_segments: output.stops.len(),
 673	        deadhead_distance_km: 0.0,
 674	        efficiency_pct: 100.0,
 675	        turns,
 676	        elapsed_ms: start.elapsed().as_millis() as u64,
 677	        num_routes: output.routes.as_ref().map(|r| r.len()).unwrap_or(1),
 678	    })
 679	}
