 821	/// Helper: build RmpNode/RmpEdge vectors from raw tuples.
 822	fn make_graph(
 823	    coords: &[(f64, f64)],
 824	    edge_defs: &[(u32, u32, f64, u8)],
 825	) -> (Vec<RmpNode>, Vec<RmpEdge>) {
 826	    let nodes: Vec<RmpNode> = coords
 827	        .iter()
 828	        .map(|&(lat, lon)| RmpNode { lat, lon })
 829	        .collect();
 830	    let edges: Vec<RmpEdge> = edge_defs
 831	        .iter()
 832	        .map(|&(from, to, weight_m, oneway)| RmpEdge { from, to, weight_m, oneway })
 833	        .collect();
 834	    (nodes, edges)
 835	}
