 894	/// **Theorem (Edge coverage)**:
 895	/// The CPP circuit must traverse every edge in the original graph at least once.
 896	/// This is the defining property of the Chinese Postman Problem.
 897	#[test]
 898	fn test_cpp_covers_all_edges() {
 899	    // 4 nodes, 5 edges (node 0 has degree 3 = odd)
 900	    let (nodes, edges) = make_graph(
 901	        &[(45.0, -73.0), (45.01, -73.0), (45.0, -73.01), (45.01, -73.01)],
 902	        &[
 903	            (0, 1, 1100.0, 0),
 904	            (0, 2, 1100.0, 0),
 905	            (1, 3, 1100.0, 0),
 906	            (2, 3, 1100.0, 0),
 907	            (0, 3, 1500.0, 0),
 908	        ],
 909	    );
 910	    let out = solve_cpp(&nodes, &edges, OnewayMode::Ignore, None).unwrap();
 911	
 912	    // Build a multiset of traversed directed edges from the circuit
 913	    let mut traversed: std::collections::HashMap<(u32, u32), u32> = std::collections::HashMap::new();
 914	    for window in out.circuit.windows(2) {
 915	        *traversed.entry((window[0], window[1])).or_insert(0) += 1;
 916	    }
