 918	    // Every original undirected edge must appear at least once (in either direction)
 919	    for (i, e) in edges.iter().enumerate() {
 920	        let forward_count = traversed.get(&(e.from, e.to)).copied().unwrap_or(0);
 921	        let reverse_count = if e.oneway == 0 {
 922	            traversed.get(&(e.to, e.from)).copied().unwrap_or(0)
 923	        } else {
 924	            0
 925	        };
 926	        assert!(
 927	            forward_count + reverse_count >= 1,
 928	            "edge {} ({}, {}) not traversed in circuit",
