 934	/// **Theorem (Handshaking lemma / Parity correction)**:
 935	/// In any graph, the number of odd-degree vertices is even.
 936	/// The CPP algorithm must add duplicate edges that pair up all odd-degree vertices,
 937	/// making every vertex even-degree. This is a necessary condition for Eulerian circuit.
 938	#[test]
 939	fn test_cpp_handshaking_lemma() {
 940	    // Path graph: A-B-C-D (3 edges, 2 odd-degree endpoints)
 941	    let (nodes, edges) = make_graph(
 942	        &[(45.0, -73.0), (45.01, -73.0), (45.02, -73.0), (45.03, -73.0)],
 943	        &[
 944	            (0, 1, 1100.0, 0),
 945	            (1, 2, 1100.0, 0),
 946	            (2, 3, 1100.0, 0),
 947	        ],
 948	    );
 949	
 950	    let n = nodes.len();
 951	    let mut degree = vec![0u32; n];
 952	    for e in &edges {
 953	        degree[e.from as usize] += 1;
 954	        if e.oneway == 0 {
 955	            degree[e.to as usize] += 1;
 956	        }
 957	    }
 958	    let odd_count = degree.iter().filter(|&&d| d % 2 == 1).count();
 959	    assert_eq!(odd_count % 2, 0, "handshaking lemma: odd-degree count must be even");
 960	
 961	    let out = solve_cpp(&nodes, &edges, OnewayMode::Ignore, None).unwrap();
 962	
 963	    // In an Eulerian circuit, every node must have even degree in the walk.
 964	    // Degree = number of times a node appears as "from" endpoint + "to" endpoint.
 965	    // For circuit [v0, v1, ..., vk] with v0 == vk, edges are (vi, vi+1).
 966	    let mut walk_degree = vec![0u32; n];
 967	    for window in out.circuit.windows(2) {
 968	        walk_degree[window[0] as usize] += 1; // "from" endpoint
 969	        walk_degree[window[1] as usize] += 1; // "to" endpoint
 970	    }
 971	    for i in 0..n {
 972	        assert_eq!(
 973	            walk_degree[i] % 2, 0,
 974	            "node {} has odd walk-degree {} in Eulerian circuit - parity violation",
 975	            i, walk_degree[i]
 976	        );
 977	    }
 978	}
