247	/// Convert an Overture segment to a GeoJSON feature
248	fn segment_to_feature(seg: OvertureSegment) -> Feature {
249	    let geometry_json = match seg.geometry {
250	        Geometry::LineString(coords) => {
251	            json!({
252	                "type": "LineString",
253	                "coordinates": coords
254	            })
255	        }
256	        Geometry::Point(lon, lat) => {
257	            json!({
258	                "type": "Point",
259	                "coordinates": [lon, lat]
260	            })
261	        }
262	    };
263	
264	    // Convert JSON to geojson::Geometry
265	    let geometry = GeoJsonGeometry::from_json_value(geometry_json)
266	        .expect("Failed to convert JSON to geojson::Geometry");
267	
268	    // Build properties map
269	    let mut props = serde_json::Map::new();
270	    props.insert("id".to_string(), serde_json::Value::String(seg.id.clone()));
271	    if let Some(ref name) = seg.name {
272	        props.insert("name".to_string(), serde_json::Value::String(name.clone()));
273	    }
274	    if let Some(ref class) = seg.class {
275	        props.insert(
276	            "class".to_string(),
277	            serde_json::Value::String(class.clone()),
278	        );
279	    }
280	    if let Some(ref subtype) = seg.subtype {
281	        props.insert(
282	            "subtype".to_string(),
283	            serde_json::Value::String(subtype.clone()),
284	        );
285	    }
286	    if let Some(ref surface) = seg.surface {
287	        props.insert(
288	            "surface".to_string(),
289	            serde_json::Value::String(surface.clone()),
290	        );
291	    }
292	    if let Some(ref oneway) = seg.oneway {
293	        props.insert(
294	            "oneway".to_string(),
295	            serde_json::Value::String(oneway.clone()),
296	        );
297	    }
298	    if let Some(ref junction) = seg.junction {
299	        props.insert(
300	            "junction".to_string(),
301	            serde_json::Value::String(junction.clone()),
302	        );
303	    }
304	    if let Some(ref osm_id) = seg.osm_id {
305	        props.insert(
306	            "osm_id".to_string(),
307	            serde_json::Value::String(osm_id.clone()),
308	        );
309	    }
310	
311	    Feature {
312	        id: None,
313	        bbox: None,
314	        geometry: Some(geometry),
315	        properties: Some(props),
316	        foreign_members: None,
317	    }
318	}
319	
320	/// Build graph statistics from features
321	fn build_graph_stats(features: &[Feature]) -> Result<(usize, usize, f64)> {
322	    // Node deduplication: snap coordinates to ~1m precision
323	    let mut node_map: HashMap<(i64, i64), usize> = HashMap::new();
324	    let mut next_node_id: usize = 0;
325	    let mut edge_count = 0;
326	    let mut total_km = 0.0;
327	
328	    for f in features {
329	        if let Some(ref geom) = f.geometry {
330	            let line_strings: Vec<&Vec<Vec<f64>>> = match &geom.value {
331	                GeoJsonValue::LineString(coords) => vec![coords],
332	                GeoJsonValue::MultiLineString(multi) => multi.iter().collect(),
333	                _ => continue,
334	            };
335	
336	            for coords in line_strings {
337	                if coords.len() < 2 {
338	                    continue;
339	                }
340	
341	                // Extract coordinates as (lon, lat) pairs
342	                let coord_points: Vec<(f64, f64)> = coords
343	                    .iter()
344	                    .filter(|p| p.len() >= 2)
345	                    .map(|p| (p[0], p[1]))
346	                    .collect();
347	
348	                // Calculate length for each segment
349	                for window in coord_points.windows(2) {
350	                    let (lon1, lat1) = window[0];
351	                    let (lon2, lat2) = window[1];
352	
353	                    // Haversine distance in km
354	                    let d = super::haversine_m(lat1, lon1, lat2, lon2) / 1000.0;
355	                    total_km += d;
356	
357	                    // Get/create node IDs
358	                    let _node1 = get_or_create_node(&mut node_map, &mut next_node_id, lon1, lat1);
359	                    let _node2 = get_or_create_node(&mut node_map, &mut next_node_id, lon2, lat2);
360	
361	                    // Count edge
362	                    edge_count += 1;
363	                }
364	            }
365	        }
366	    }
367	
368	    Ok((node_map.len(), edge_count, total_km))
369	}
370	
371	/// Get or create a node ID for given coordinates
372	fn get_or_create_node(
373	    node_map: &mut HashMap<(i64, i64), usize>,
374	    next_node_id: &mut usize,
375	    lon: f64,
376	    lat: f64,
377	) -> usize {
378	    // Snap to ~1m precision (6 decimal places)
379	    let key = ((lon * 1e6) as i64, (lat * 1e6) as i64);
380	    *node_map.entry(key).or_insert_with(|| {
381	        let id = *next_node_id;
382	        *next_node_id += 1;
383	        id
384	    })
385	}
