1116	async fn handle_vrp_solve(args: &Value) -> Result<Value> {
1117	    let stops_val = args
1118	        .get("stops")
1119	        .and_then(|v| v.as_array())
1120	        .ok_or_else(|| anyhow::anyhow!("Missing 'stops' parameter"))?;
1121	
1122	    if stops_val.is_empty() {
1123	        anyhow::bail!("At least one stop (the depot) is required");
1124	    }
1125	
1126	    let stops: Vec<VRPSolverStop> = stops_val
1127	        .iter()
1128	        .enumerate()
1129	        .map(|(i, s)| {
1130	            let lat = s.get("lat").and_then(|v| v.as_f64())
1131	                .ok_or_else(|| anyhow::anyhow!("Stop {} missing 'lat'", i))?;
1132	            let lon = s.get("lon").and_then(|v| v.as_f64())
1133	                .ok_or_else(|| anyhow::anyhow!("Stop {} missing 'lon'", i))?;
1134	            let label = s.get("label").and_then(|v| v.as_str())
1135	                .unwrap_or_else(|| "")
1136	                .to_string();
1137	            let demand = s.get("demand").and_then(|v| v.as_f64());
1138	            Ok(VRPSolverStop {
1139	                lat,
1140	                lon,
1141	                label: if label.is_empty() { format!("Stop {}", i) } else { label },
1142	                demand,
1143	                arrival_time: None,
1144	            })
1145	        })
1146	        .collect::<Result<Vec<_>>>()?;
1147	
1148	    let num_vehicles = args.get("num_vehicles").and_then(|v| v.as_u64()).unwrap_or(1) as usize;
1149	    let vehicle_capacity = args.get("vehicle_capacity").and_then(|v| v.as_f64()).unwrap_or(100.0);
1150	    let solver_id = args.get("solver_id").and_then(|v| v.as_str()).unwrap_or("default").to_string();
1151	    let avg_speed_kmh = args.get("avg_speed_kmh").and_then(|v| v.as_f64()).unwrap_or(40.0);
1152	    let objective = match args.get("objective").and_then(|v| v.as_str()).unwrap_or("min_distance") {
1153	        "min_time" => VrpObjective::MinTime,
1154	        "balance_load" => VrpObjective::BalanceLoad,
1155	        "min_vehicles" => VrpObjective::MinVehicles,
1156	        _ => VrpObjective::MinDistance,
1157	    };
1158	
1159	    // Build haversine distance matrix
1160	    let matrix = build_haversine_matrix(&stops, avg_speed_kmh);
1161	
1162	    let input = VRPSolverInput {
1163	        locations: stops,
1164	        num_vehicles,
1165	        vehicle_capacity,
1166	        objective,
1167	        matrix: Some(matrix),
