1169	        use_time_windows: false,
1170	        window_open: None,
1171	        window_close: None,
1172	    };
1173	
1174	    tracing::info!("vrp_solve: {} stops, {} vehicles, solver={}", 
1175	        input.locations.len(), num_vehicles, solver_id);
1176	
1177	    let output = solve_with(&solver_id, &input).await
1178	        .map_err(|e| anyhow::anyhow!("VRP solver failed: {}", e))?;
1179	
1180	    // Convert routes to JSON
1181	    let routes_json: Vec<Value> = output.routes.iter().flatten().enumerate().map(|(vi, route)| {
1182	        let stops_json: Vec<Value> = route.iter().map(|s| {
1183	            json!({
