1185	                "lon": s.lon,
1186	                "label": s.label,
1187	                "demand": s.demand,
1188	            })
1189	        }).collect();
1190	        json!({
1191	            "vehicle": vi,
1192	            "stops": stops_json,
1193	        })
1194	    }).collect();
1195	
1196	    Ok(json!({
1197	        "total_distance_km": output.total_distance_km,
1198	        "total_time_min": output.total_time_min,
1199	        "routes": routes_json,
1200	        "unassigned": output.unassigned,
