1420	fn handle_fuel_estimate(args: &Value) -> Result<Value> {
1421	    let samples_val = args
1422	        .get("samples")
1423	        .and_then(|v| v.as_array())
1424	        .ok_or_else(|| anyhow::anyhow!("Missing 'samples' parameter"))?;
1425	
1426	    if samples_val.len() < 2 {
1427	        anyhow::bail!("At least 2 samples are required for fuel estimation");
1428	    }
1429	
1430	    let base_consumption = args
1431	        .get("base_consumption")
1432	        .and_then(|v| v.as_f64())
1433	        .unwrap_or(0.08);
1434	
1435	    // Build an ElevationProfile from the samples
1436	    let points: Vec<v2rmp::core::elevation::RouteElevationPoint> = samples_val
1437	        .iter()
1438	        .enumerate()
1439	        .map(|(i, s)| {
1440	            let distance_m = s.get("distance_m").and_then(|v| v.as_f64())
1441	                .ok_or_else(|| anyhow::anyhow!("Sample {} missing 'distance_m'", i))?;
1442	            let elevation_m = s.get("elevation_m").and_then(|v| v.as_f64())
1443	                .ok_or_else(|| anyhow::anyhow!("Sample {} missing 'elevation_m'", i))?;
1444	            Ok(v2rmp::core::elevation::RouteElevationPoint {
1445	                distance_m,
1446	                elevation_m: Some(elevation_m),
1447	                point: v2rmp::core::elevation::Point { lon: 0.0, lat: 0.0 },
1448	            })
1449	        })
1450	        .collect::<Result<Vec<_>>>()?;
1451	
1452	    let total_distance_km = points.last().map(|p| p.distance_m / 1000.0).unwrap_or(0.0);
1453	
1454	    let profile = v2rmp::core::elevation::ElevationProfile {
1455	        points,
1456	        total_ascent: 0.0, // Not needed for fuel calc
1457	        total_descent: 0.0,
1458	        max_elevation: 0.0,
1459	        min_elevation: 0.0,
1460	        avg_elevation: 0.0,
1461	        distance_km: total_distance_km,
1462	    };
1463	
1464	    let consumption = FuelCalculator::calculate(&profile, base_consumption);
1465	
1466	    Ok(json!({
