1469	        "elevation_penalty_l": consumption.elevation_penalty_l,
1470	        "elevation_benefit_l": consumption.elevation_benefit_l,
1471	        "base_consumption_l_per_km": base_consumption,
1472	        "distance_km": total_distance_km,
