1476	// ── Inspect RMP handler ──────────────────────────────────────────────────
1477	
1478	fn handle_inspect_rmp(args: &Value) -> Result<Value> {
1479	    let input = args
1480	        .get("input")
1481	        .and_then(|v| v.as_str())
1482	        .ok_or_else(|| anyhow::anyhow!("Missing 'input' parameter"))?;
1483	
1484	    let file_data = std::fs::read(input)
1485	        .map_err(|e| anyhow::anyhow!("Failed to read .rmp file: {}", e))?;
1486	
1487	    let (nodes, edges) = v2rmp::core::optimize::read_rmp_file(&file_data)?;
1488	
1489	    // Compute bounding box from nodes
1490	    let (min_lat, max_lat, min_lon, max_lon) = if nodes.is_empty() {
1491	        (0.0, 0.0, 0.0, 0.0)
1492	    } else {
1493	        nodes.iter().fold(
1494	            (f64::MAX, f64::MIN, f64::MAX, f64::MIN),
1495	            |(mn_lat, mx_lat, mn_lon, mx_lon), n| {
1496	                (mn_lat.min(n.lat), mx_lat.max(n.lat), mn_lon.min(n.lon), mx_lon.max(n.lon))
1497	            },
1498	        )
1499	    };
1500	
1501	    let total_edge_length_km: f64 = edges.iter().map(|e| e.weight_m / 1000.0).sum();
1502	
1503	    Ok(json!({
1504	        "node_count": nodes.len(),
1505	        "edge_count": edges.len(),
1506	        "bbox": {
1507	            "min_lat": min_lat,
1508	            "max_lat": max_lat,
1509	            "min_lon": min_lon,
1510	            "max_lon": max_lon,
1511	        },
1512	        "total_edge_length_km": total_edge_length_km,
1513	        "file_size_bytes": file_data.len(),
1514	    }))
1515	}
