1743	// ── Pipeline handler ─────────────────────────────────────────────────────
1744	
1745	async fn handle_pipeline(args: &Value) -> Result<Value> {
1746	    let bbox = parse_bbox(args)?;
1747	    let output_dir = args
1748	        .get("output_dir")
1749	        .and_then(|v| v.as_str())
1750	        .unwrap_or("./pipeline-output")
1751	        .to_string();
1752	    let source = match args.get("source").and_then(|v| v.as_str()).unwrap_or("overture") {
1753	        "osm" => ExtractSource::Osm,
1754	        _ => ExtractSource::Overture,
1755	    };
1756	    let pbf_path = args.get("pbf_path").and_then(|v| v.as_str()).map(String::from);
1757	    let depot = args.get("depot").and_then(|d| {
1758	        let lat = d.get("lat")?.as_f64()?;
1759	        let lon = d.get("lon")?.as_f64()?;
1760	        Some((lat, lon))
1761	    });
1762	    let mode = parse_solver_mode(args);
1763	    let prune_disconnected = args.get("prune_disconnected").and_then(|v| v.as_bool()).unwrap_or(false);
1764	
1765	    // Ensure output directory exists
1766	    std::fs::create_dir_all(&output_dir)?;
1767	
1768	    let extract_path = format!("{}/extract.geojson", output_dir);
1769	    let cleaned_path = format!("{}/cleaned.geojson", output_dir);
1770	    let rmp_path = format!("{}/network.rmp", output_dir);
1771	    let route_path = format!("{}/route.gpx", output_dir);
1772	
1773	    // Stage 1: Extract
1774	    tracing::info!("pipeline stage 1: extract");
1775	    let extract_req = ExtractRequest {
1776	        source,
1777	        bbox,
1778	        road_classes: RoadClass::all_vehicle(),
1779	        output_path: extract_path.clone(),
1780	        pbf_path,
1781	    };
1782	    let extract_result = v2rmp::core::extract::run_extract(&extract_req).await?;
1783	
1784	    // Stage 2: Clean
1785	    tracing::info!("pipeline stage 2: clean");
1786	    let input_data = std::fs::read_to_string(&extract_path)?;
1787	    let geojson: geojson::FeatureCollection = serde_json::from_str(&input_data)?;
1788	    let (cleaned, clean_stats, _warnings) = clean_geojson(&geojson, &CleanOptions::default())?;
1789	    let cleaned_str = serde_json::to_string_pretty(&cleaned)?;
1790	    std::fs::write(&cleaned_path, &cleaned_str)?;
1791	
1792	    // Stage 3: Compile
1793	    tracing::info!("pipeline stage 3: compile");
1794	    let compile_req = CompileRequest {
1795	        input_geojson: cleaned_path.clone(),
1796	        output_rmp: rmp_path.clone(),
1797	        compress: false,
1798	        road_classes: vec![],
1799	        clean_options: None,
1800	        prune_disconnected,
1801	    };
1802	    let compile_result = v2rmp::core::compile::run_compile(&compile_req)?;
1803	
1804	    // Stage 4: Optimize
