  1	//! Zilliz-MCP-Server — MCP (Model Context Protocol) server exposing
  2	//! semantic codebase search over the v2rmp Zilliz Cloud vector database.
  3	//!
  4	//! Runs over stdio with JSON-RPC 2.0 framing, one line per message.
  5	//!
  6	//! Tools exposed:
  7	//!   - `search_codebase` — embed a natural-language query via Ollama and
  8	//!     return the top-k code chunks from the v2rmp vector DB.
  9	//!
 10	//! Connect from any MCP client (Claude Desktop, Continue, Cursor, etc.)
 11	//! by adding to the client's config:
 12	//!
 13	//! ```json
 14	//! {
 15	//!   "mcpServers": {
 16	//!     "zilliz-codebase": {
 17	//!       "command": "cargo",
 18	//!       "args": ["run", "--bin", "zilliz-mcp-server", "--release"]
 19	//!     }
 20	//!   }
 21	//! }
 22	//! ```
 23	
 24	use anyhow::{Context, Result};
 25	use serde::{Deserialize, Serialize};
 26	use serde_json::{json, Value};
 27	use std::io::{BufRead, Write};
 28	
 29	// ── Config (same as zilliz_embed_pipeline.py / VECTOR_DB_CONFIG.md) ────────
 30	
 31	const ZILLIZ_URI: &str =
 32	    "https://in05-895d375123308f8.serverless.aws-eu-central-1.cloud.zilliz.com";
 33	fn zilliz_token() -> Result<String> {
 34	    std::env::var("ZILLIZ_TOKEN")
 35	        .context("ZILLIZ_TOKEN environment variable not set")
 36	}
 37	const OLLAMA_URL: &str = "http://localhost:11434/api/embed";
 38	const EMBED_MODEL: &str = "mxbai-embed-large";
 39	const COLLECTION: &str = "v2rmp_codebase";
 40	const DIMENSION: usize = 1024;
 41	
 42	// ── JSON-RPC / MCP types ───────────────────────────────────────────────────
 43	
 44	#[derive(Debug, Deserialize)]
 45	struct Request {
 46	    jsonrpc: String,
 47	    method: String,
 48	    #[serde(default)]
 49	    params: Value,
 50	    #[serde(default)]
 51	    #[allow(dead_code)]
 52	    id: Value,
