 63	// ── Ollama embed helper ────────────────────────────────────────────────────
 64	
 65	async fn ollama_embed(query: &str) -> Result<Vec<Vec<f32>>> {
 66	    let client = reqwest::Client::new();
 67	    let body = json!({
 68	        "model": EMBED_MODEL,
 69	        "input": [query]
 70	    });
 71	
 72	    let resp = client
 73	        .post(OLLAMA_URL)
 74	        .json(&body)
 75	        .send()
 76	        .await
 77	        .context("Ollama request failed — is it running?")?;
 78	
 79	    let data: Value = resp.json().await.context("Ollama response parse")?;
 80	    let embeddings: Vec<Vec<f32>> =
 81	        serde_json::from_value(data["embeddings"].clone()).context("bad embeddings shape")?;
 82	    Ok(embeddings)
 83	}
