234	#[tokio::main]
235	async fn main() -> Result<()> {
236	    // Stderr for logging so it doesn't corrupt the stdio JSON-RPC stream
237	    eprintln!("zilliz-mcp-server starting (collection={COLLECTION}, model={EMBED_MODEL})");
238	
239	    let stdin = std::io::stdin().lock();
240	    for line in stdin.lines() {
241	        let line = line?;
242	        if line.trim().is_empty() {
243	            continue;
244	        }
245	
246	        let req: Request = match serde_json::from_str(&line) {
247	            Ok(r) => r,
248	            Err(e) => {
249	                send_err(&Value::Null, -32700, &format!("Parse error: {e}"));
250	                continue;
251	            }
252	        };
253	
254	        if req.jsonrpc != "2.0" {
255	            send_err(&req.id, -32600, "Invalid Request: jsonrpc must be 2.0");
256	            continue;
257	        }
258	
259	        match req.method.as_str() {
260	            // ── initialize ────────────────────────────────────────────
261	            "initialize" => {
262	                send(
263	                    &req.id,
264	                    json!({
265	                        "protocolVersion": "2024-11-05",
266	                        "capabilities": {
267	                            "tools": {}
268	                        },
269	                        "serverInfo": {
270	                            "name": "zilliz-mcp-server",
271	                            "version": env!("CARGO_PKG_VERSION")
272	                        }
273	                    }),
274	                );
275	            }
276	
277	            // ── tools/list ────────────────────────────────────────────
278	            "tools/list" => {
279	                let tools = vec![ToolDef {
280	                    name: "search_codebase".into(),
281	                    description: concat!(
282	                        "Semantic search over the v2rmp (rmpca) Rust codebase. ",
283	                        "Embeds your natural-language query with mxbai-embed-large ",
284	                        "and retrieves the most relevant code chunks from the Zilliz ",
285	                        "vector database. Returns file path, line range, code snippet, ",
286	                        "and L2 similarity score for each match."
287	                    ).into(),
288	                    input_schema: json!({
289	                        "type": "object",
290	                        "properties": {
291	                            "query": {
292	                                "type": "string",
293	                                "description": "Natural-language search query, e.g. 'How does the VRP solver optimize routes?'"
294	                            },
295	                            "limit": {
296	                                "type": "integer",
297	                                "description": "Max results (default: 10, max: 50)",
298	                                "default": 10
299	                            }
300	                        },
301	                        "required": ["query"]
302	                    }),
303	                }];
304	                send(&req.id, json!({ "tools": tools }));
305	            }
306	
307	            // ── tools/call ────────────────────────────────────────────
308	            "tools/call" => {
309	                let name = req.params.get("name").and_then(|v| v.as_str()).unwrap_or("");
310	                let args = req.params.get("arguments").cloned().unwrap_or(Value::Null);
311	
312	                match name {
313	                    "search_codebase" => match handle_search_codebase(&args).await {
314	                        Ok(result) => {
315	                            send(
316	                                &req.id,
317	                                json!({
318	                                    "content": [{
319	                                        "type": "text",
320	                                        "text": serde_json::to_string_pretty(&result).unwrap_or_default()
321	                                    }]
322	                                }),
323	                            );
324	                        }
325	                        Err(e) => {
326	                            send(
327	                                &req.id,
328	                                json!({
329	                                    "content": [{
330	                                        "type": "text",
331	                                        "text": format!("Error: {e:#}")
332	                                    }],
333	                                    "isError": true
334	                                }),
335	                            );
336	                        }
337	                    },
338	                    other => {
339	                        send_err(
