 155	/// Classify a turn by bearing delta (degrees).
 156	/// Returns "straight", "right", "left", or "u_turn".
 157	pub fn classify_turn(bearing_delta: f64) -> &'static str {
 158	    let d = bearing_delta.normalize(-180.0, 180.0);
 159	    if d.abs() <= 45.0 {
 160	        "straight"
 161	    } else if d > 45.0 && d <= 135.0 {
 162	        "right"
 163	    } else if (-135.0..-45.0).contains(&d) {
 164	        "left"
 165	    } else {
 166	        "u_turn"
 167	    }
 168	}
