 188	// ── Binary parser ────────────────────────────────────────────────────
 189	
 190	/// Magic bytes for the .rmp binary format.
 191	const RMP_MAGIC: &[u8; 4] = b"RMP1";
 192	
 193	/// Parse an `.rmp` binary file and return (nodes, edges).
 194	pub fn read_rmp_file(data: &[u8]) -> anyhow::Result<(Vec<RmpNode>, Vec<RmpEdge>)> {
 195	    // Validate magic
 196	    if data.len() < 4 || &data[..4] != RMP_MAGIC {
 197	        anyhow::bail!("Invalid .rmp file: missing RMP1 magic bytes");
 198	    }
 199	
 200	    if data.len() < 12 {
 201	        anyhow::bail!("Invalid .rmp file: header too short");
 202	    }
 203	
 204	    let node_count = u32::from_le_bytes(data[4..8].try_into()?) as usize;
 205	    let edge_count = u32::from_le_bytes(data[8..12].try_into()?) as usize;
 206	
 207	    let nodes_end = 12 + node_count * 16;
 208	    let edges_end = nodes_end + edge_count * 17;
 209	    let expected_len = edges_end + 4;
 210	
 211	    if data.len() < expected_len {
 212	        anyhow::bail!(
 213	            "Invalid .rmp file: expected {} bytes, got {}",
 214	            expected_len,
 215	            data.len()
 216	        );
 217	    }
 218	
 219	    // Parse nodes
 220	    let mut nodes = Vec::with_capacity(node_count);
 221	    for i in 0..node_count {
 222	        let offset = 12 + i * 16;
 223	        let lat = f64::from_le_bytes(data[offset..offset + 8].try_into()?);
 224	        let lon = f64::from_le_bytes(data[offset + 8..offset + 16].try_into()?);
 225	        nodes.push(RmpNode { lat, lon });
 226	    }
 227	
 228	    // Parse edges
 229	    let mut edges = Vec::with_capacity(edge_count);
 230	    for i in 0..edge_count {
 231	        let offset = nodes_end + i * 17;
 232	        let from = u32::from_le_bytes(data[offset..offset + 4].try_into()?);
 233	        let to = u32::from_le_bytes(data[offset + 4..offset + 8].try_into()?);
 234	        let weight_m = f64::from_le_bytes(data[offset + 8..offset + 16].try_into()?);
 235	        let oneway = data[offset + 16];
 236	        edges.push(RmpEdge {
 237	            from,
 238	            to,
 239	            weight_m,
 240	            oneway,
 241	        });
 242	    }
 243	
 244	    // Verify CRC32
 245	    let expected_crc = u32::from_le_bytes(data[edges_end..edges_end + 4].try_into()?);
 246	    let actual_crc = crc32fast::hash(&data[..edges_end]);
 247	    if expected_crc != actual_crc {
 248	        anyhow::bail!(
 249	            "Invalid .rmp file: CRC32 mismatch (expected {}, got {})",
 250	            expected_crc,
 251	            actual_crc
 252	        );
 253	    }
 254	
 255	    Ok((nodes, edges))
 256	}
