 282	/// In-memory CPP result: both the summary stats and the ordered node-IDs of the Eulerian circuit.
 283	#[derive(Debug, Clone)]
 284	pub struct CppOutput {
 285	    /// Summary statistics (distance, turns, etc.)
 286	    pub summary: OptimizeResult,
 287	    /// Ordered node indices forming the Eulerian circuit.
 288	    pub circuit: Vec<u32>,
 289	}
 290	
 291	/// Solve the Chinese Postman Problem directly from an in-memory graph.
 292	///
 293	/// This is the pure algorithm — no filesystem dependency.
 294	/// - `depot` is an optional (lat, lon) — the solver snaps to the nearest node.
 295	///
 296	/// Returns a `CppOutput` with both summary statistics and the full circuit.
 297	pub fn solve_cpp(nodes: &[RmpNode], edges: &[RmpEdge], oneway: OnewayMode, depot: Option<(f64, f64)>) -> anyhow::Result<CppOutput> {
 298	    let start = Instant::now();
 299	
 300	    if nodes.is_empty() || edges.is_empty() {
 301	        return Ok(CppOutput {
 302	            summary: OptimizeResult {
 303	                total_distance_km: 0.0,
 304	                total_segments: 0,
 305	                deadhead_distance_km: 0.0,
 306	                efficiency_pct: 100.0,
 307	                turns: TurnSummary { left: 0, right: 0, u_turn: 0, straight: 0 },
 308	                elapsed_ms: 0,
 309	                num_routes: 1,
 310	            },
 311	            circuit: Vec::new(),
 312	        });
 313	    }
 314	
 315	    // Build adjacency list
 316	    let n = nodes.len();
 317	    let mut adj: Vec<Vec<AdjEntry>> = vec![vec![]; n];
 318	
 319	    for (idx, edge) in edges.iter().enumerate() {
 320	        let from = edge.from as usize;
 321	        let to = edge.to as usize;
 322	
 323	        adj[from].push(AdjEntry { to: edge.to, weight_m: edge.weight_m, edge_idx: idx });
 324	
 325	        match oneway {
 326	            OnewayMode::Ignore => {
 327	                adj[to].push(AdjEntry { to: edge.from, weight_m: edge.weight_m, edge_idx: idx });
 328	            }
 329	            OnewayMode::Respect => {
 330	                if edge.oneway == 0 {
 331	                    adj[to].push(AdjEntry { to: edge.from, weight_m: edge.weight_m, edge_idx: idx });
 332	                }
 333	            }
 334	            OnewayMode::Reverse => {
 335	                if edge.oneway == 1 {
 336	                    adj[to].push(AdjEntry { to: edge.from, weight_m: edge.weight_m, edge_idx: idx });
 337	                    adj[from].retain(|e| e.edge_idx != idx);
 338	                } else {
 339	                    adj[to].push(AdjEntry { to: edge.from, weight_m: edge.weight_m, edge_idx: idx });
 340	                }
 341	            }
 342	        }
 343	    }
 344	
 345	    // Find odd-degree vertices
 346	    let mut degrees = vec![0usize; n];
 347	    for (i, adj_list) in adj.iter().enumerate() {
 348	        degrees[i] = adj_list.len();
 349	    }
 350	    let odd_vertices: Vec<usize> = (0..n).filter(|&i| !degrees[i].is_multiple_of(2)).collect();
 351	
 352	    // Minimum weight perfect matching (greedy nearest-neighbor using Dijkstra)
 353	    let mut duplicate_edges: Vec<(usize, usize, f64, usize)> = Vec::new();
 354	    let mut matched = vec![false; n];
 355	    for i in 0..n {
 356	        if degrees[i].is_multiple_of(2) {
 357	            matched[i] = true;
 358	        }
 359	    }
 360	
 361	    use std::collections::BinaryHeap;
 362	    use std::cmp::Ordering;
 363	
 364	    #[derive(Copy, Clone, PartialEq)]
 365	    struct State {
 366	        cost: f64,
 367	        position: usize,
 368	    }
 369	    impl Eq for State {}
 370	    impl Ord for State {
 371	        fn cmp(&self, other: &Self) -> Ordering {
 372	            other.cost.partial_cmp(&self.cost).unwrap_or(Ordering::Equal)
 373	        }
 374	    }
 375	    impl PartialOrd for State {
 376	        fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
 377	            Some(self.cmp(other))
 378	        }
 379	    }
 380	
 381	    for &u in &odd_vertices {
 382	        if matched[u] { continue; }
 383	
 384	        let mut dists = vec![f64::MAX; n];
 385	        let mut prev = vec![None; n];
 386	        let mut heap = BinaryHeap::new();
 387	
 388	        dists[u] = 0.0;
 389	        heap.push(State { cost: 0.0, position: u });
 390	
 391	        let mut best_v = None;
 392	
 393	        while let Some(State { cost, position }) = heap.pop() {
 394	            if cost > dists[position] { continue; }
 395	
 396	            if position != u && !matched[position] {
 397	                best_v = Some(position);
 398	                break;
 399	            }
 400	
 401	            for edge in &adj[position] {
 402	                let next = State { cost: cost + edge.weight_m, position: edge.to as usize };
 403	                if next.cost < dists[next.position] {
 404	                    dists[next.position] = next.cost;
 405	                    prev[next.position] = Some((position, edge.weight_m, edge.edge_idx));
 406	                    heap.push(next);
 407	                }
 408	            }
 409	        }
 410	
 411	        if let Some(v) = best_v {
 412	            matched[u] = true;
 413	            matched[v] = true;
 414	
 415	            // Trace path back from v to u
 416	            let mut curr = v;
 417	            while let Some((p, weight, eidx)) = prev[curr] {
 418	                duplicate_edges.push((p, curr, weight, eidx));
 419	                curr = p;
 420	            }
 421	        } else {
 422	            // Fallback: If disconnected, just skip (graph must be disconnected)
 423	            matched[u] = true;
 424	        }
 425	    }
 426	
 427	    // Add duplicate edges
 428	    let deadhead_edge_idx = usize::MAX;
 429	    for &(u, v, weight, eidx) in &duplicate_edges {
 430	        adj[u].push(AdjEntry { to: v as u32, weight_m: weight, edge_idx: eidx });
 431	        adj[v].push(AdjEntry { to: u as u32, weight_m: weight, edge_idx: eidx });
 432	    }
 433	
 434	    // Find Eulerian circuit using Hierholzer's algorithm
 435	    let start_node = if let Some((dep_lat, dep_lon)) = depot {
 436	        let mut best_node = 0;
 437	        let mut best_dist = f64::MAX;
 438	        for (i, node) in nodes.iter().enumerate() {
 439	            let dist = haversine_m(dep_lat, dep_lon, node.lat, node.lon);
 440	            if dist < best_dist { best_dist = dist; best_node = i; }
 441	        }
 442	        best_node
 443	    } else if !odd_vertices.is_empty() {
 444	        odd_vertices[0]
 445	    } else {
 446	        0
 447	    };
 448	
 449	    let mut stack = vec![(start_node as u32, None)];
 450	    let mut circuit_with_edges: Vec<(u32, Option<AdjEntry>)> = Vec::new();
 451	
 452	    while let Some(&(v_u32, _)) = stack.last() {
 453	        let v = v_u32 as usize;
 454	        if let Some(edge) = adj[v].pop() {
 455	            if let Some(pos) = adj[edge.to as usize].iter().position(|e| {
 456	                e.to == v as u32 && e.edge_idx == edge.edge_idx && e.weight_m == edge.weight_m
 457	            }) {
 458	                adj[edge.to as usize].swap_remove(pos);
 459	            }
 460	            stack.push((edge.to, Some(edge)));
 461	        } else if let Some((v_u32, e)) = stack.pop() {
 462	            circuit_with_edges.push((v_u32, e));
 463	        }
 464	    }
 465	
 466	    circuit_with_edges.reverse();
 467	    let circuit: Vec<u32> = circuit_with_edges.iter().map(|(v, _)| *v).collect();
 468	
 469	    // Compute total distance, deadhead distance, and turn summary
 470	    let mut total_distance_m = 0.0;
 471	    let mut deadhead_distance_m = 0.0;
 472	    let mut total_segments = 0usize;
 473	    let mut turns = TurnSummary { left: 0, right: 0, u_turn: 0, straight: 0 };
 474	    let mut edge_traversal_count = vec![0u32; edges.len()];
 475	
 476	    for entry in circuit_with_edges.iter().skip(1) {
 477	        if let Some(e) = &entry.1 {
 478	            total_distance_m += e.weight_m;
 479	            total_segments += 1;
 480	            if e.edge_idx == deadhead_edge_idx {
 481	                deadhead_distance_m += e.weight_m;
 482	            } else {
 483	                edge_traversal_count[e.edge_idx] += 1;
 484	                if edge_traversal_count[e.edge_idx] > 1 {
 485	                    deadhead_distance_m += e.weight_m;
 486	                }
 487	            }
 488	        }
 489	    }
 490	
 491	    // Turn classification
 492	    if circuit.len() > 2 {
 493	        for i in 1..circuit.len().saturating_sub(1) {
 494	            let prev = circuit[i - 1] as usize;
 495	            let curr = circuit[i] as usize;
 496	            let next = circuit[i + 1] as usize;
 497	            if prev == curr || curr == next { continue; }
 498	            let b_in = bearing(nodes[prev].lat, nodes[prev].lon, nodes[curr].lat, nodes[curr].lon);
 499	            let b_out = bearing(nodes[curr].lat, nodes[curr].lon, nodes[next].lat, nodes[next].lon);
 500	            let b_in_reverse = (b_in + 180.0).normalize(0.0, 360.0);
 501	            let delta = b_out - b_in_reverse;
 502	            match classify_turn(delta) {
 503	                "left" => turns.left += 1,
 504	                "right" => turns.right += 1,
 505	                "u_turn" => turns.u_turn += 1,
 506	                _ => turns.straight += 1,
 507	            }
 508	        }
 509	    }
 510	
 511	    // Compute efficiency
 512	    let effective_distance_m = total_distance_m - deadhead_distance_m;
 513	    let efficiency_pct = if total_distance_m > 0.0 {
 514	        (effective_distance_m / total_distance_m) * 100.0
 515	    } else {
 516	        100.0
 517	    };
 518	
 519	    let elapsed_ms = start.elapsed().as_millis() as u64;
 520	
 521	    Ok(CppOutput {
 522	        summary: OptimizeResult {
 523	            total_distance_km: total_distance_m / 1000.0,
 524	            total_segments,
 525	            deadhead_distance_km: deadhead_distance_m / 1000.0,
 526	            efficiency_pct,
 527	            turns,
 528	            elapsed_ms,
 529	            num_routes: 1,
 530	        },
 531	        circuit,
 532	    })
 533	}
