 535	/// Run the Chinese Postman Problem route optimization (filesystem wrapper).
 536	fn run_cpp_optimize(req: &OptimizeRequest) -> anyhow::Result<OptimizeResult> {
 537	    let start = Instant::now();
 538	
 539	    let mut file_data = Vec::new();
 540	    {
 541	        let mut file = std::fs::File::open(&req.cache_file)
 542	            .map_err(|e| anyhow::anyhow!("Failed to open .rmp file '{}': {}", req.cache_file, e))?;
 543	        file.read_to_end(&mut file_data)?;
 544	    }
 545	    let (nodes, edges) = read_rmp_file(&file_data)?;
 546	
 547	    let output = solve_cpp(&nodes, &edges, req.oneway_mode, req.depot)?;
 548	
 549	    if let Some(ref route_path) = req.route_file {
 550	        if route_path.ends_with(".json") {
 551	            let route_json = serde_json::json!({
 552	                "route": output.circuit,
 553	                "total_distance_km": output.summary.total_distance_km,
 554	                "deadhead_distance_km": output.summary.deadhead_distance_km,
 555	                "efficiency_pct": output.summary.efficiency_pct,
 556	                "nodes": nodes.iter().enumerate().map(|(i, n)| serde_json::json!({ "id": i, "lat": n.lat, "lon": n.lon })).collect::<Vec<_>>(),
 557	            });
 558	            std::fs::write(route_path, serde_json::to_string_pretty(&route_json)?)?;
 559	        } else {
 560	            write_gpx_cpp(route_path, &nodes, &output.circuit)?;
 561	        }
 562	    }
 563	
 564	    let mut result = output.summary;
 565	    result.elapsed_ms = start.elapsed().as_millis() as u64;
 566	    Ok(result)
 567	}
