 681	pub(crate) fn write_gpx_multi(path: &str, routes: &[Vec<VRPSolverStop>]) -> anyhow::Result<()> {
 682	    use std::io::Write;
 683	    let mut file = std::fs::File::create(path)?;
 684	
 685	    writeln!(file, "<?xml version=\"1.0\" encoding=\"UTF-8\"?>")?;
 686	    writeln!(
 687	        file,
 688	        "<gpx version=\"1.1\" creator=\"rmpca\" xmlns=\"http://www.topografix.com/GPX/1/1\">"
 689	    )?;
 690	    for (i, route) in routes.iter().enumerate() {
 691	        writeln!(file, "  <trk>")?;
 692	        writeln!(file, "    <name>Optimized Route {}</name>", i + 1)?;
 693	        writeln!(file, "    <trkseg>")?;
 694	        for stop in route {
 695	            writeln!(
 696	                file,
 697	                "      <trkpt lat=\"{:.7}\" lon=\"{:.7}\"></trkpt>",
 698	                stop.lat, stop.lon
 699	            )?;
 700	        }
 701	        writeln!(file, "    </trkseg>")?;
 702	        writeln!(file, "  </trk>")?;
 703	    }
 704	    writeln!(file, "</gpx>")?;
 705	
 706	    Ok(())
 707	}
