 980	/// **Theorem (Optimality on Eulerian graphs)**:
 981	/// If the original graph is already Eulerian (all vertices even degree),
 982	/// the CPP solution must equal the Eulerian circuit with zero deadhead.
 983	/// No edges need to be duplicated.
 984	#[test]
 985	fn test_cpp_eulerian_graph_zero_deadhead() {
 986	    // Square: A-B-C-D-A - all vertices degree 2 (Eulerian)
 987	    let (nodes, edges) = make_graph(
 988	        &[(45.0, -73.0), (45.01, -73.0), (45.01, -73.01), (45.0, -73.01)],
 989	        &[
 990	            (0, 1, 1100.0, 0),
 991	            (1, 2, 1100.0, 0),
 992	            (2, 3, 1100.0, 0),
 993	            (3, 0, 1100.0, 0),
 994	        ],
 995	    );
 996	    let out = solve_cpp(&nodes, &edges, OnewayMode::Ignore, None).unwrap();
 997	
 998	    let sum_weights_km: f64 = edges.iter().map(|e| e.weight_m / 1000.0).sum();
 999	    let tolerance = 0.01;
1000	
1001	    assert!(
1002	        (out.summary.deadhead_distance_km - 0.0).abs() < tolerance,
1003	        "Eulerian graph must have zero deadhead, got {:.6} km",
1004	        out.summary.deadhead_distance_km
1005	    );
1006	    assert!(
1007	        (out.summary.total_distance_km - sum_weights_km).abs() < tolerance,
1008	        "Eulerian graph: total distance {:.6} km should equal sum of weights {:.6} km",
1009	        out.summary.total_distance_km, sum_weights_km
1010	    );
1011	    assert!(
1012	        out.summary.efficiency_pct > 99.9,
1013	        "Eulerian graph must have ~100% efficiency, got {:.1}%",
1014	        out.summary.efficiency_pct
1015	    );
1016	}
1017	
1018	/// **Theorem (Deadhead correctness on non-Eulerian graphs)**:
1019	/// If the graph is not Eulerian, the CPP solver must add deadhead edges.
1020	/// The total distance must equal the sum of original edge weights plus
1021	/// deadhead distance. This is a conservation law.
1022	#[test]
1023	fn test_cpp_distance_conservation() {
1024	    // Path graph (non-Eulerian): A-B-C
1025	    let (nodes, edges) = make_graph(
1026	        &[(45.0, -73.0), (45.01, -73.0), (45.02, -73.0)],
1027	        &[
1028	            (0, 1, 1100.0, 0),
1029	            (1, 2, 1100.0, 0),
1030	        ],
1031	    );
1032	    let out = solve_cpp(&nodes, &edges, OnewayMode::Ignore, None).unwrap();
1033	
1034	    let sum_weights_km: f64 = edges.iter().map(|e| e.weight_m / 1000.0).sum();
1035	    let expected_total = sum_weights_km + out.summary.deadhead_distance_km;
1036	    let tolerance = 0.01;
1037	
1038	    assert!(
1039	        (out.summary.total_distance_km - expected_total).abs() < tolerance,
1040	        "distance conservation: total ({:.6}) should equal original ({:.6}) + deadhead ({:.6})",
1041	        out.summary.total_distance_km, sum_weights_km, out.summary.deadhead_distance_km
1042	    );
1043	
1044	    assert!(
1045	        out.summary.deadhead_distance_km > 0.0,
1046	        "non-Eulerian graph must have positive deadhead, got 0"
1047	    );
1048	}
1049	
1050	/// **Theorem (Circuit connectivity / Valid walk)**:
1051	/// Every consecutive pair in the circuit must correspond to an actual edge
1052	/// in the graph (original or duplicate). This is the "valid walk" property.
1053	#[test]
1054	fn test_cpp_circuit_is_valid_walk() {
1055	    // Cycle graph (Eulerian): A-B-C-D-E-A - all vertices degree 2
1056	    // Using an Eulerian graph means no deadhead edges are added,
1057	    // so every circuit step must be an original edge.
1058	    let (nodes, edges) = make_graph(
1059	        &[
1060	            (45.0, -73.0),
1061	            (45.01, -73.0),
1062	            (45.01, -73.01),
1063	            (45.0, -73.02),
1064	            (44.99, -73.01),
1065	        ],
1066	        &[
1067	            (0, 1, 1100.0, 0),
1068	            (1, 2, 1100.0, 0),
1069	            (2, 3, 1100.0, 0),
1070	            (3, 4, 1100.0, 0),
1071	            (4, 0, 1100.0, 0),
1072	        ],
1073	    );
1074	    let out = solve_cpp(&nodes, &edges, OnewayMode::Ignore, None).unwrap();
1075	
1076	    let mut adj: std::collections::HashSet<(u32, u32)> = std::collections::HashSet::new();
1077	    for e in &edges {
1078	        adj.insert((e.from, e.to));
1079	        if e.oneway == 0 {
1080	            adj.insert((e.to, e.from));
1081	        }
1082	    }
1083	
1084	    for (i, window) in out.circuit.windows(2).enumerate() {
1085	        let (a, b) = (window[0], window[1]);
1086	        assert!(
1087	            adj.contains(&(a, b)),
1088	            "circuit step {}: ({}, {}) is not a valid edge",
1089	            i, a, b
1090	        );
1091	    }
1092	
1093	    assert_eq!(
1094	        out.circuit.first(), out.circuit.last(),
1095	        "circuit must start and end at the same node"
1096	    );
1097	}
1098	
1099	/// **Theorem (Single edge graph)**:
1100	/// The CPP algorithm must handle the degenerate case of a single edge.
1101	/// The circuit should traverse it forward and back (deadhead = edge weight).
1102	#[test]
1103	fn test_cpp_single_edge() {
1104	    let (nodes, edges) = make_graph(
1105	        &[(45.0, -73.0), (45.01, -73.0)],
1106	        &[(0, 1, 1100.0, 0)],
1107	    );
1108	    let out = solve_cpp(&nodes, &edges, OnewayMode::Ignore, None).unwrap();
1109	
1110	    assert!(out.circuit.len() >= 2, "circuit must have at least 2 nodes for 1 edge");
1111	    assert_eq!(out.circuit.first(), out.circuit.last(), "circuit must be closed");
1112	    assert!(out.circuit.contains(&0), "node 0 must appear in circuit");
1113	    assert!(out.circuit.contains(&1), "node 1 must appear in circuit");
1114	
1115	    let edge_km = 1100.0 / 1000.0;
1116	    assert!(
1117	        out.summary.total_distance_km >= edge_km - 0.01,
1118	        "total distance must be at least the edge weight"
1119	    );
1120	}
1121	
1122	/// **Theorem (One-way constraint)**:
1123	/// When one-way streets are respected, the circuit must never traverse
1124	/// a one-way edge in the reverse direction.
1125	#[test]
1126	fn test_cpp_oneway_respected() {
1127	    let (nodes, edges) = make_graph(
1128	        &[(45.0, -73.0), (45.01, -73.0)],
1129	        &[(0, 1, 1100.0, 1)], // oneway = 1
1130	    );
1131	    let out = solve_cpp(&nodes, &edges, OnewayMode::Respect, None).unwrap();
1132	
1133	    for window in out.circuit.windows(2) {
1134	        let (a, b) = (window[0], window[1]);
1135	        assert!(
1136	            !(a == 1 && b == 0),
1137	            "circuit traverses one-way edge backwards: (1, 0)"
1138	        );
1139	    }
1140	}
1141	
1142	/// **Theorem (Empty graph base case)**:
1143	/// The CPP algorithm must return an empty circuit for an empty graph
1144	/// without panicking.
1145	#[test]
1146	fn test_cpp_empty_graph() {
1147	    let nodes: Vec<RmpNode> = vec![];
1148	    let edges: Vec<RmpEdge> = vec![];
1149	    let out = solve_cpp(&nodes, &edges, OnewayMode::Ignore, None).unwrap();
1150	
1151	    assert!(out.circuit.is_empty(), "empty graph must produce empty circuit");
1152	    assert_eq!(out.summary.total_distance_km, 0.0);
1153	    assert_eq!(out.summary.total_segments, 0);
1154	    assert_eq!(out.summary.deadhead_distance_km, 0.0);
1155	}
1156	
1157	/// **Theorem (Depot snapping)**:
1158	/// When a depot is specified, the CPP circuit must start at the node
1159	/// closest to the depot coordinates.
1160	#[test]
1161	fn test_cpp_depot_snapping() {
1162	    let (nodes, edges) = make_graph(
1163	        &[(45.0, -73.0), (45.01, -73.0), (45.02, -73.0)],
1164	        &[
1165	            (0, 1, 1100.0, 0),
1166	            (1, 2, 1100.0, 0),
1167	        ],
1168	    );
1169	
1170	    let out = solve_cpp(&nodes, &edges, OnewayMode::Ignore, Some((45.01, -73.0))).unwrap();
1171	
1172	    assert_eq!(
1173	        out.circuit.first().copied(),
1174	        Some(1u32),
1175	        "circuit must start at node closest to depot"
1176	    );
1177	    assert_eq!(
1178	        out.circuit.last().copied(),
1179	        Some(1u32),
1180	        "circuit must end at depot node (closed tour)"
1181	    );
1182	}
1183	
1184	/// **Theorem (No edge left behind / Completeness)**:
1185	/// For a graph with many edges, every single edge must be traversed at least once.
1186	/// This is the completeness guarantee of CPP.
1187	#[test]
1188	fn test_cpp_completeness_large() {
1189	    // Grid: 3x3 nodes, 12 edges
1190	    let coords: Vec<(f64, f64)> = (0..3)
1191	        .flat_map(|r| (0..3).map(move |c| (45.0 + r as f64 * 0.01, -73.0 + c as f64 * 0.01)))
1192	        .collect();
1193	    let mut edge_defs: Vec<(u32, u32, f64, u8)> = Vec::new();
1194	    for r in 0u32..3 {
1195	        for c in 0u32..3 {
1196	            let idx = r * 3 + c;
1197	            if c < 2 {
1198	                edge_defs.push((idx, idx + 1, 1100.0, 0));
1199	            }
1200	            if r < 2 {
1201	                edge_defs.push((idx, idx + 3, 1100.0, 0));
1202	            }
1203	        }
1204	    }
1205	
1206	    let (nodes, edges) = make_graph(&coords, &edge_defs);
1207	    let out = solve_cpp(&nodes, &edges, OnewayMode::Ignore, None).unwrap();
1208	
1209	    let mut traversed: std::collections::HashMap<(u32, u32), u32> = std::collections::HashMap::new();
1210	    for window in out.circuit.windows(2) {
1211	        *traversed.entry((window[0], window[1])).or_insert(0) += 1;
1212	    }
1213	
1214	    for (i, e) in edges.iter().enumerate() {
1215	        let fwd = traversed.get(&(e.from, e.to)).copied().unwrap_or(0);
1216	        let rev = if e.oneway == 0 {
1217	            traversed.get(&(e.to, e.from)).copied().unwrap_or(0)
1218	        } else {
1219	            0
1220	        };
1221	        assert!(
1222	            fwd + rev >= 1,
1223	            "edge {} ({}, {}) not covered - CPP completeness violation",
1224	            i, e.from, e.to
1225	        );
1226	    }
1227	}
1228	
1229	}
