  44	// ── JSON-RPC / MCP types ───────────────────────────────────────────────────
  45	
  46	#[derive(Debug, Deserialize)]
  47	struct Request {
  48	    jsonrpc: String,
  49	    method: String,
  50	    #[serde(default)]
  51	    params: Value,
  52	    #[serde(default)]
  53	    id: Value,
  54	}
  55	
  56	#[derive(Debug)]
  57	struct ToolDef {
  58	    name: &'static str,
  59	    description: &'static str,
  60	    input_schema: Value,
  61	}
  62	
  63	// ── Protocol helpers ────────────────────────────────────────────────────────
  64	
  65	fn send(id: &Value, result: Value) {
  66	    let out = json!({
  67	        "jsonrpc": "2.0",
  68	        "id": id,
  69	        "result": result
  70	    });
  71	    let mut stdout = std::io::stdout().lock();
  72	    let _ = writeln!(stdout, "{out}");
  73	    let _ = stdout.flush();
  74	}
  75	
  76	fn send_err(id: &Value, code: i64, msg: &str) {
  77	    let out = json!({
  78	        "jsonrpc": "2.0",
  79	        "id": id,
  80	        "error": { "code": code, "message": msg }
  81	    });
  82	    let mut stdout = std::io::stdout().lock();
  83	    let _ = writeln!(stdout, "{out}");
  84	    let _ = stdout.flush();
  85	}
  86	
  87	fn tool_success(id: &Value, result: &Result<Value>) {
  88	    match result {
  89	        Ok(val) => send(
  90	            id,
  91	            json!({
  92	                "content": [{
  93	                    "type": "text",
  94	                    "text": serde_json::to_string_pretty(val).unwrap_or_default()
  95	                }]
  96	            }),
  97	        ),
  98	        Err(e) => send(
  99	            id,
 100	            json!({
 101	                "content": [{
 102	                    "type": "text",
 103	                    "text": format!("Error: {e:#}")
 104	                }],
 105	                "isError": true
 106	            }),
 107	        ),
 108	    }
 109	}
