 813	fn parse_bbox(args: &Value) -> anyhow::Result<BBoxRequest> {
 814	    let bbox = args
 815	        .get("bbox")
 816	        .ok_or_else(|| anyhow::anyhow!("Missing 'bbox' parameter"))?;
 817	    Ok(BBoxRequest {
 818	        min_lon: bbox
 819	            .get("min_lon")
 820	            .and_then(|v| v.as_f64())
 821	            .ok_or_else(|| anyhow::anyhow!("bbox.min_lon required"))?,
 822	        min_lat: bbox
 823	            .get("min_lat")
 824	            .and_then(|v| v.as_f64())
 825	            .ok_or_else(|| anyhow::anyhow!("bbox.min_lat required"))?,
 826	        max_lon: bbox
 827	            .get("max_lon")
 828	            .and_then(|v| v.as_f64())
 829	            .ok_or_else(|| anyhow::anyhow!("bbox.max_lon required"))?,
 830	        max_lat: bbox
 831	            .get("max_lat")
 832	            .and_then(|v| v.as_f64())
 833	            .ok_or_else(|| anyhow::anyhow!("bbox.max_lat required"))?,
 834	    })
 835	}
