 837	fn parse_road_classes(args: &Value) -> Vec<RoadClass> {
 838	    let Some(arr) = args.get("road_classes").and_then(|v| v.as_array()) else {
 839	        return RoadClass::all_vehicle();
 840	    };
 841	    if arr.is_empty() {
 842	        return RoadClass::all_vehicle();
 843	    }
 844	    arr.iter()
 845	        .filter_map(|v| v.as_str())
 846	        .filter_map(|s| match s {
 847	            "residential" => Some(RoadClass::Residential),
 848	            "tertiary" => Some(RoadClass::Tertiary),
 849	            "secondary" => Some(RoadClass::Secondary),
 850	            "primary" => Some(RoadClass::Primary),
 851	            "trunk" => Some(RoadClass::Trunk),
 852	            "motorway" => Some(RoadClass::Motorway),
 853	            "unclassified" => Some(RoadClass::Unclassified),
 854	            "living_street" => Some(RoadClass::LivingStreet),
 855	            "service" => Some(RoadClass::Service),
 856	            "secondary_link" => Some(RoadClass::SecondaryLink),
 857	            "primary_link" => Some(RoadClass::PrimaryLink),
 858	            "trunk_link" => Some(RoadClass::TrunkLink),
 859	            "motorway_link" => Some(RoadClass::MotorwayLink),
 860	            _ => None,
 861	        })
 862	        .collect()
 863	}
 864	
 865	fn parse_oneway_mode(args: &Value) -> OnewayMode {
 866	    match args
 867	        .get("oneway_mode")
 868	        .and_then(|v| v.as_str())
 869	        .unwrap_or("respect")
 870	    {
 871	        "ignore" => OnewayMode::Ignore,
 872	        "reverse" => OnewayMode::Reverse,
 873	        _ => OnewayMode::Respect,
 874	    }
 875	}
 876	
 877	fn parse_solver_mode(args: &Value) -> SolverMode {
 878	    match args
 879	        .get("mode")
 880	        .and_then(|v| v.as_str())
 881	        .unwrap_or("cpp")
 882	    {
 883	        "vrp" => SolverMode::Vrp,
 884	        _ => SolverMode::Cpp,
 885	    }
 886	}
