 939	fn handle_compile(args: &Value) -> Result<Value> {
 940	    let input = args
 941	        .get("input")
 942	        .and_then(|v| v.as_str())
 943	        .ok_or_else(|| anyhow::anyhow!("Missing 'input' parameter"))?
 944	        .to_string();
 945	    let output = args
 946	        .get("output")
 947	        .and_then(|v| v.as_str())
 948	        .ok_or_else(|| anyhow::anyhow!("Missing 'output' parameter"))?
 949	        .to_string();
 950	    let clean = args
 951	        .get("clean")
 952	        .and_then(|v| v.as_bool())
 953	        .unwrap_or(false);
 954	    let prune = args
 955	        .get("prune_disconnected")
 956	        .and_then(|v| v.as_bool())
 957	        .unwrap_or(false);
 958	
 959	    let clean_options = if clean {
 960	        Some(v2rmp::core::clean::CleanOptions::default())
 961	    } else {
 962	        None
 963	    };
 964	
 965	    tracing::info!("compile: {} -> {}", input, output);
 966	
 967	    let req = CompileRequest {
 968	        input_geojson: input,
 969	        output_rmp: output,
 970	        compress: false,
 971	        road_classes: vec![],
 972	        clean_options,
 973	        prune_disconnected: prune,
 974	    };
 975	
 976	    let result: CompileResult = v2rmp::core::compile::run_compile(&req)?;
 977	    Ok(serde_json::to_value(result)?)
