 980	async fn handle_optimize(args: &Value) -> Result<Value> {
 981	    let input = args
 982	        .get("input")
 983	        .and_then(|v| v.as_str())
 984	        .ok_or_else(|| anyhow::anyhow!("Missing 'input' parameter"))?
 985	        .to_string();
 986	    let route_file = args.get("output").and_then(|v| v.as_str()).map(String::from);
 987	    let depot = args
 988	        .get("depot")
 989	        .and_then(|d| {
 990	            let lat = d.get("lat")?.as_f64()?;
 991	            let lon = d.get("lon")?.as_f64()?;
 992	            Some((lat, lon))
 993	        });
 994	    let oneway_mode = parse_oneway_mode(args);
 995	    let mode = parse_solver_mode(args);
 996	    let left = args
 997	        .get("left_penalty")
 998	        .and_then(|v| v.as_f64())
 999	        .unwrap_or(1.0);
1000	    let right = args
1001	        .get("right_penalty")
1002	        .and_then(|v| v.as_f64())
1003	        .unwrap_or(0.0);
1004	    let u_turn = args
1005	        .get("uturn_penalty")
1006	        .and_then(|v| v.as_f64())
1007	        .unwrap_or(5.0);
1008	    let num_vehicles = args
1009	        .get("num_vehicles")
1010	        .and_then(|v| v.as_u64())
1011	        .unwrap_or(1) as usize;
1012	    let solver_id = args
1013	        .get("solver_id")
1014	        .and_then(|v| v.as_str())
1015	        .unwrap_or("default")
1016	        .to_string();
1017	
1018	    tracing::info!("optimize: input={}", input);
1019	
1020	    let req = OptimizeRequest {
1021	        cache_file: input,
1022	        route_file,
1023	        turn_penalties: TurnPenalties {
1024	            left,
1025	            right,
1026	            u_turn,
1027	        },
1028	        depot,
1029	        oneway_mode,
1030	        mode,
1031	        num_vehicles,
1032	        solver_id,
1033	    };
1034	
1035	    let result: OptimizeResult = v2rmp::core::optimize::run_optimize(&req).await?;
1036	    Ok(serde_json::to_value(result)?)
1037	}
