1048	        .get("output")
1049	        .and_then(|v| v.as_str())
1050	        .ok_or_else(|| anyhow::anyhow!("Missing 'output' parameter"))?
1051	        .to_string();
1052	
1053	    // Build CleanOptions from args, using defaults where not specified
1054	    let defaults = CleanOptions::default();
1055	    let options = CleanOptions {
1056	        make_valid: args.get("make_valid").and_then(|v| v.as_bool()).unwrap_or(defaults.make_valid),
1057	        drop_invalid: args.get("drop_invalid").and_then(|v| v.as_bool()).unwrap_or(defaults.drop_invalid),
1058	        remove_selfloops: args.get("remove_selfloops").and_then(|v| v.as_bool()).unwrap_or(defaults.remove_selfloops),
1059	        min_length_m: args.get("min_length_m").and_then(|v| v.as_f64()).unwrap_or(defaults.min_length_m),
1060	        node_snap_m: args.get("node_snap_m").and_then(|v| v.as_f64()).unwrap_or(defaults.node_snap_m),
1061	        node_precision_decimals: args.get("node_precision_decimals").and_then(|v| v.as_u64()).map(|v| v as u32).unwrap_or(defaults.node_precision_decimals),
1062	        merge_node_positions: args.get("merge_node_positions").and_then(|v| v.as_bool()).unwrap_or(defaults.merge_node_positions),
1063	        dedupe_edges: args.get("dedupe_edges").and_then(|v| v.as_bool()).unwrap_or(defaults.dedupe_edges),
1064	        remove_isolates: args.get("remove_isolates").and_then(|v| v.as_bool()).unwrap_or(defaults.remove_isolates),
1065	        max_components: args.get("max_components").and_then(|v| v.as_u64()).map(|v| v as usize).unwrap_or(defaults.max_components),
1066	        required_attrs: args.get("required_attrs").and_then(|v| v.as_array()).map(|arr| {
1067	            arr.iter().filter_map(|v| v.as_str().map(String::from)).collect()
