1477	
1478	fn handle_inspect_rmp(args: &Value) -> Result<Value> {
1479	    let input = args
1480	        .get("input")
1481	        .and_then(|v| v.as_str())
1482	        .ok_or_else(|| anyhow::anyhow!("Missing 'input' parameter"))?;
