1491	        (0.0, 0.0, 0.0, 0.0)
1492	    } else {
1493	        nodes.iter().fold(
1494	            (f64::MAX, f64::MIN, f64::MAX, f64::MIN),
1495	            |(mn_lat, mx_lat, mn_lon, mx_lon), n| {
1496	                (mn_lat.min(n.lat), mx_lat.max(n.lat), mn_lon.min(n.lon), mx_lon.max(n.lon))
1497	            },
1498	        )
1499	    };
1500	
1501	    let total_edge_length_km: f64 = edges.iter().map(|e| e.weight_m / 1000.0).sum();
