148	// ── Tool: search_codebase ──────────────────────────────────────────────────
149	
150	async fn handle_search_codebase(args: &Value) -> Result<Value> {
151	    let query = args
152	        .get("query")
153	        .and_then(|v| v.as_str())
154	        .unwrap_or("")
155	        .trim()
156	        .to_string();
157	
158	    if query.is_empty() {
159	        anyhow::bail!("Missing 'query' parameter");
160	    }
161	
162	    let limit = args
163	        .get("limit")
164	        .and_then(|v| v.as_u64())
165	        .unwrap_or(10)
166	        .min(50) as usize;
167	
168	    // 1. Embed
169	    let embeddings = ollama_embed(&query).await?;
170	    let vector = embeddings
171	        .first()
172	        .context("Ollama returned empty embeddings")?;
173	
174	    if vector.len() != DIMENSION {
175	        anyhow::bail!(
176	            "Ollama returned {}-dim embedding; expected {DIMENSION}",
177	            vector.len()
178	        );
179	    }
180	
181	    // 2. Search
182	    let hits = zilliz_search(vector, limit).await?;
183	
184	    // 3. Format
185	    let items: Vec<Value> = hits
186	        .into_iter()
187	        .filter_map(|h| {
188	            Some(json!({
189	                "file": h.file?,
190	                "start_line": h.start_line?,
191	                "end_line": h.end_line?,
192	                "code": h.code?,
193	                "score": h.distance?,
194	            }))
195	        })
196	        .collect();
197	
198	    Ok(json!({
199	        "query": query,
200	        "results": items,
201	        "count": items.len(),
202	        "embedding_model": EMBED_MODEL,
203	        "metric": "L2 (lower = more similar)"
204	    }))
205	}
206	
207	// ── Main loop ──────────────────────────────────────────────────────────────
208	
209	fn send(id: &Value, result: Value) {
210	    let out = json!({
211	        "jsonrpc": "2.0",
212	        "id": id,
213	        "result": result
214	    });
215	    let mut stdout = std::io::stdout().lock();
216	    let _ = writeln!(stdout, "{out}");
217	    let _ = stdout.flush();
218	}
219	
220	fn send_err(id: &Value, code: i64, msg: &str) {
221	    let out = json!({
222	        "jsonrpc": "2.0",
223	        "id": id,
224	        "error": {
225	            "code": code,
226	            "message": msg
227	        }
228	    });
229	    let mut stdout = std::io::stdout().lock();
230	    let _ = writeln!(stdout, "{out}");
231	    let _ = stdout.flush();
232	}
233	
234	#[tokio::main]
235	async fn main() -> Result<()> {
236	    // Stderr for logging so it doesn't corrupt the stdio JSON-RPC stream
237	    eprintln!("zilliz-mcp-server starting (collection={COLLECTION}, model={EMBED_MODEL})");
238	
239	    let stdin = std::io::stdin().lock();
240	    for line in stdin.lines() {
241	        let line = line?;
242	        if line.trim().is_empty() {
243	            continue;
244	        }
245	
246	        let req: Request = match serde_json::from_str(&line) {
247	            Ok(r) => r,
248	            Err(e) => {
249	                send_err(&Value::Null, -32700, &format!("Parse error: {e}"));
250	                continue;
251	            }
252	        };
253	
254	        if req.jsonrpc != "2.0" {
255	            send_err(&req.id, -32600, "Invalid Request: jsonrpc must be 2.0");
256	            continue;
257	        }
258	
259	        match req.method.as_str() {
260	            // ── initialize ────────────────────────────────────────────
261	            "initialize" => {
262	                send(
263	                    &req.id,
264	                    json!({
265	                        "protocolVersion": "2024-11-05",
266	                        "capabilities": {
267	                            "tools": {}
268	                        },
269	                        "serverInfo": {
270	                            "name": "zilliz-mcp-server",
271	                            "version": env!("CARGO_PKG_VERSION")
272	                        }
273	                    }),
274	                );
275	            }
276	
277	            // ── tools/list ────────────────────────────────────────────
278	            "tools/list" => {
279	                let tools = vec![ToolDef {
280	                    name: "search_codebase".into(),
281	                    description: concat!(
282	                        "Semantic search over the v2rmp (rmpca) Rust codebase. ",
283	                        "Embeds your natural-language query with mxbai-embed-large ",
284	                        "and retrieves the most relevant code chunks from the Zilliz ",
285	                        "vector database. Returns file path, line range, code snippet, ",
286	                        "and L2 similarity score for each match."
287	                    ).into(),
288	                    input_schema: json!({
289	                        "type": "object",
290	                        "properties": {
291	                            "query": {
292	                                "type": "string",
293	                                "description": "Natural-language search query, e.g. 'How does the VRP solver optimize routes?'"
294	                            },
295	                            "limit": {
296	                                "type": "integer",
297	                                "description": "Max results (default: 10, max: 50)",
298	                                "default": 10
299	                            }
300	                        },
301	                        "required": ["query"]
302	                    }),
303	                }];
304	                send(&req.id, json!({ "tools": tools }));
305	            }
306	
307	            // ── tools/call ────────────────────────────────────────────
308	            "tools/call" => {
309	                let name = req.params.get("name").and_then(|v| v.as_str()).unwrap_or("");
310	                let args = req.params.get("arguments").cloned().unwrap_or(Value::Null);
311	
312	                match name {
313	                    "search_codebase" => match handle_search_codebase(&args).await {
314	                        Ok(result) => {
315	                            send(
316	                                &req.id,
317	                                json!({
318	                                    "content": [{
319	                                        "type": "text",
320	                                        "text": serde_json::to_string_pretty(&result).unwrap_or_default()
321	                                    }]
322	                                }),
323	                            );
324	                        }
325	                        Err(e) => {
326	                            send(
327	                                &req.id,
328	                                json!({
329	                                    "content": [{
330	                                        "type": "text",
331	                                        "text": format!("Error: {e:#}")
332	                                    }],
333	                                    "isError": true
334	                                }),
335	                            );
336	                        }
337	                    },
338	                    other => {
339	                        send_err(
340	                            &req.id,
341	                            -32602,
342	                            &format!("Unknown tool: {other}"),
343	                        );
344	                    }
345	                }
346	            }
347	
348	            // ── notifications (no response) ───────────────────────────
349	            "notifications/initialized" | "initialized" => {
350	                // No response needed — MCP spec: client sends this after
351	                // receiving the initialize response.
352	            }
353	
354	            // ── unrecognized ──────────────────────────────────────────
355	            other => {
356	                send_err(&req.id, -32601, &format!("Method not found: {other}"));
357	            }
358	        }
359	    }
360	
361	    Ok(())
362	}

