  1	//! Clarke-Wright Savings algorithm for VRP with balanced distribution.
  2	//!
  3	//! Depot is index 0. Merges on highest savings first but caps route size so
  4	//! stops are spread evenly across drivers; then force-merges smallest routes
  5	//! if needed.
  6	
  7	use super::super::types::*;
  8	use super::super::utils::{matrix_get_dist, matrix_get_time};
  9	
 10	fn solve(matrix: &DistMatrix, num_vehicles: usize) -> SolveResult {
 11	    let n = matrix.len();
 12	    if n <= 1 {
 13	        return SolveResult {
 14	            routes: vec![vec![0]],
 15	            total_distance: 0.0,
 16	            total_time: 0.0,
 17	        };
 18	    }
 19	
 20	    let max_intermediate = ((n - 1) as f64 / num_vehicles as f64).ceil() as usize;
 21	    let cap = max_intermediate + 1;
 22	
 23	    let mut savings: Vec<(usize, usize, f64)> = Vec::new();
 24	    for i in 1..n {
 25	        for j in (i + 1)..n {
 26	            let s = matrix_get_dist(matrix, 0, i) + matrix_get_dist(matrix, 0, j)
 27	                - matrix_get_dist(matrix, i, j);
 28	            savings.push((i, j, s));
 29	        }
 30	    }
 31	    savings.sort_by(|a, b| b.2.partial_cmp(&a.2).unwrap_or(std::cmp::Ordering::Equal));
 32	
 33	    let mut routes: Vec<Vec<usize>> = (1..n).map(|i| vec![0, i, 0]).collect();
 34	
 35	    let find_route = |node: usize, routes: &[Vec<usize>]| -> Option<usize> {
 36	        routes.iter().position(|r| r.contains(&node))
 37	    };
 38	
 39	    let intermediate_count = |r: &[usize]| -> usize {
 40	        if r.len() > 2 {
 41	            r.len() - 2
 42	        } else {
 43	            0
 44	        }
 45	    };
 46	
 47	    for &(i, j, _) in &savings {
 48	        if routes.len() <= num_vehicles {
 49	            break;
 50	        }
 51	        let ri = match find_route(i, &routes) {
 52	            Some(idx) => idx,
 53	            None => continue,
 54	        };
 55	        let rj = match find_route(j, &routes) {
 56	            Some(idx) => idx,
 57	            None => continue,
 58	        };
 59	        if ri == rj {
 60	            continue;
 61	        }
 62	
 63	        let ra = &routes[ri];
 64	        let rb = &routes[rj];
 65	        let end_of_a = ra[ra.len() - 2];
 66	        let start_of_b = rb[1];
 67	
 68	        let merged = if (end_of_a == i && start_of_b == j) || (end_of_a == j && start_of_b == i) {
 69	            let mut m = ra[..ra.len() - 1].to_vec();
 70	            m.extend_from_slice(&rb[1..]);
 71	            Some(m)
 72	        } else {
 73	            let ra_rev: Vec<usize> = ra.iter().copied().rev().collect();
 74	            let rb_rev: Vec<usize> = rb.iter().copied().rev().collect();
 75	            let end_rev_a = ra_rev[ra_rev.len() - 2];
 76	            let start_rev_b = rb_rev[1];
 77	            if (end_rev_a == i && start_rev_b == j) || (end_rev_a == j && start_rev_b == i) {
 78	                let mut m = ra_rev[..ra_rev.len() - 1].to_vec();
 79	                m.extend_from_slice(&rb_rev[1..]);
 80	                Some(m)
 81	            } else {
 82	                None
 83	            }
 84	        };
 85	
 86	        let merged = match merged {
 87	            Some(m) => m,
 88	            None => continue,
 89	        };
 90	
 91	        if intermediate_count(&merged) > cap {
 92	            continue;
 93	        }
 94	
 95	        let mut new_routes: Vec<Vec<usize>> = routes
 96	            .iter()
 97	            .enumerate()
 98	            .filter(|(idx, _)| *idx != ri && *idx != rj)
 99	            .map(|(_, r)| r.clone())
100	            .collect();
101	        new_routes.push(merged);
102	        routes = new_routes;
103	    }
104	
105	    // Force-merge remaining excess routes
106	    while routes.len() > num_vehicles {
107	        let mut best_i = 0;
108	        let mut best_j = 1;
109	        let mut best_merged: Option<Vec<usize>> = None;
110	        let mut best_cost = f64::INFINITY;
111	
112	        for i in 0..routes.len() {
113	            for j in (i + 1)..routes.len() {
114	                let ra = &routes[i];
115	                let rb = &routes[j];
116	
117	                let candidates: Vec<Vec<usize>> = vec![
118	                    {
119	                        let mut m = ra[..ra.len() - 1].to_vec();
120	                        m.extend_from_slice(&rb[1..]);
121	                        m
122	                    },
123	                    {
124	                        let mut m = ra[..ra.len() - 1].to_vec();
125	                        m.extend(rb[1..rb.len() - 1].iter().rev());
126	                        m.push(0);
127	                        m
128	                    },
129	                    {
130	                        let mut m = vec![0];
131	                        m.extend(rb[1..rb.len() - 1].iter().rev());
132	                        m.extend_from_slice(&ra[1..]);
133	                        m
134	                    },
135	                    {
136	                        let mut m = vec![0];
137	                        m.extend_from_slice(&rb[1..]);
138	                        m.extend_from_slice(&ra[1..]);
139	                        m
140	                    },
141	                ];
142	
143	                for merged in &candidates {
144	                    if merged.len() < 3 {
145	                        continue;
146	                    }
147	                    let cost: f64 = (0..merged.len() - 1)
148	                        .map(|k| matrix_get_dist(matrix, merged[k], merged[k + 1]))
149	                        .sum();
150	                    if cost < best_cost {
151	                        best_cost = cost;
152	                        best_i = i;
153	                        best_j = j;
154	                        best_merged = Some(merged.clone());
155	                    }
156	                }
157	            }
158	        }
159	
160	        match best_merged {
161	            Some(merged) => {
162	                let mut new_routes: Vec<Vec<usize>> = routes
163	                    .iter()
164	                    .enumerate()
165	                    .filter(|(idx, _)| *idx != best_i && *idx != best_j)
166	                    .map(|(_, r)| r.clone())
167	                    .collect();
168	                new_routes.push(merged);
169	                routes = new_routes;
170	            }
171	            None => break,
172	        }
173	    }
174	
175	    let mut total_distance = 0.0;
176	    let mut total_time = 0.0;
177	    for r in &routes {
178	        for k in 0..r.len() - 1 {
179	            total_distance += matrix_get_dist(matrix, r[k], r[k + 1]);
180	            total_time += matrix_get_time(matrix, r[k], r[k + 1]);
181	        }
182	    }
183	
184	    SolveResult {
185	        routes,
186	        total_distance,
187	        total_time,
188	    }
189	}
