 23	impl LocalDem {
 24	    /// Open a DEM file (GeoTIFF, etc.) and prepare for elevation queries.
 25	    pub fn open(path: &Path) -> Result<Self> {
 26	        let dataset = Dataset::open(path)
 27	            .with_context(|| format!("Failed to open DEM file: {}", path.display()))?;
 28	
 29	        let geo_transform = dataset.geo_transform()
 30	            .context("DEM file has no geo transform")?;
 31	        let size = dataset.raster_size();
 32	
 33	        let rasterband = dataset.rasterband(1)
 34	            .context("DEM file has no raster band")?;
 35	        let nodata = rasterband.no_data_value();
 36	
 37	        Ok(Self {
 38	            dataset,
 39	            geo_transform,
 40	            size,
 41	            band_index: 1,
 42	            nodata,
 43	        })
 44	    }
 45	
 46	    /// Return the bounding box of the DEM in WGS84 (min_lon, min_lat, max_lon, max_lat).
 47	    pub fn bbox(&self) -> BBox {
 48	        let gt = &self.geo_transform;
 49	        let (w, h) = self.size;
 50	
 51	        let x_0 = gt[0];
 52	        let y_0 = gt[3];
 53	        let x_1 = gt[0] + w as f64 * gt[1];
 54	        let y_1 = gt[3] + h as f64 * gt[5];
 55	
 56	        BBox {
 57	            min_lon: x_0.min(x_1),
 58	            min_lat: y_0.min(y_1),
 59	            max_lon: x_0.max(x_1),
 60	            max_lat: y_0.max(y_1),
 61	        }
